scenarios.example_code:
import { openSession, postTurn } from '@projexlight/sdk-conversation';
const { session_id } = await openSession({
  tenant_id, channel_kind: 'patient-provider',
  participants: [patient_persona_id, provider_persona_id],
});
await postTurn({ session_id, author_persona_id: patient_persona_id, body: 'Hi, my rash has spread.' });

import { postTurn, requestHandoff, acceptHandoff } from '@projexlight/sdk-conversation';
await postTurn({ session_id, author_persona_id: AI_PERSONA, body: 'I can help with billing questions. What's your invoice number?' });
// ...AI determines it needs human help...
const { handoff_id } = await requestHandoff({ session_id, from_persona_id: AI_PERSONA, to_persona_id: HUMAN_AGENT, reason: 'requires policy override' });
await acceptHandoff({ handoff_id, accepted_by_persona_id: HUMAN_AGENT });

// The E6 cloud-builder front-end opens a session per build attempt:
const { session_id } = await openSession({
  tenant_id, channel_kind: 'cloud-builder',
  participants: [user_persona_id, BUILDER_AGENT_PERSONA],
});
// Every user message + every agent step → postTurn

// postTurn for an AI author stamps the ai_gateway.completion.id into the turn metadata:
await postTurn({
  session_id, author_persona_id: AGENT_PERSONA, author_kind: 'agent',
  body: completion.message.content,
  ai_metadata: { completion_id: completion.id, provider: completion.provider, model: completion.model, usage: completion.usage },
});

import { closeSession } from '@projexlight/sdk-conversation';
await closeSession({
  session_id, resolution: 'resolved',
  retention_policy_id: 'hipaa-7y',
});
